leerAreaMapa(){try{const area=JSON.parse(localStorage.getItem('bon_gestion_almacen_area_mapa')||'{}');this.estado.mapaAreaX=Math.max(0,Math.floor(Number(area.columnas)||0));this.estado.mapaAreaY=Math.max(0,Math.floor(Number(area.filas)||0));this.estado.mapaAltura=Math.max(0,Math.min(1400,Math.floor(Number(area.altura)||0)))}catch(ignorar){this.estado.mapaAreaX=0;this.estado.mapaAreaY=0;this.estado.mapaAltura=0}},
