formatoEjeDecomiso(valor){const numero=Math.max(0,Number(valor)||0);if(numero>=1000000)return'RD$ '+(numero/1000000).toLocaleString('es-DO',{maximumFractionDigits:1})+' MM';if(numero>=1000)return'RD$ '+(numero/1000).toLocaleString('es-DO',{maximumFractionDigits:0})+' mil';return'RD$ '+numero.toLocaleString('es-DO',{maximumFractionDigits:0})},
