 basePT.forEach(x=>{const clave=String(x.periodo||'').slice(0,7);if(!clave)return;if(!porPeriodo[clave])porPeriodo[clave]={periodo:clave,departamentos:{}};if(!Object.keys(porPeriodo[clave].departamentos).some(nombre=>this.claveDepartamentoDecomiso(nombre)==='PT'))porPeriodo[clave].departamentos.PT=Number(x.valor||0)});
