 const acumulado={};Object.values(porPeriodo).filter(x=>!periodo||x.periodo===periodo).forEach(x=>Object.keys(x.departamentos).forEach(nombre=>{const canonica=Object.keys(acumulado).find(k=>this.claveDepartamentoDecomiso(k)===this.claveDepartamentoDecomiso(nombre))||nombre;acumulado[canonica]=(acumulado[canonica]||0)+Number(x.departamentos[nombre]||0)}));
