 const barras=serie.map((p,i)=>{const centro=xCentro(i),activo=periodoActivo===p.periodo,orden=[...nombres].map(nombre=>({nombre,valor:Math.max(0,this.valorDepartamentoDecomiso(p.departamentos,nombre))})).filter(x=>x.valor>0).sort((a,b)=>b.valor-a.valor),anchoBase=Math.min(45,paso*.48),detalle=orden.map((x,j)=>{const anchoBarra=Math.max(12,anchoBase-j*7),desplazamiento=(j-(orden.length-1)/2)*7,arriba=y(x.valor);return`<rect class="gal-chart-barra gal-chart-barra-departamento" style="--gal-serie-color:${this.colorDepartamentoDecomiso(x.nombre)};--gal-serie-opacidad:${j?'.78':'1'}" x="${centro-anchoBarra/2+desplazamiento}" y="${arriba}" width="${anchoBarra}" height="${Math.max(0,base-arriba)}" rx="5"><title>${this.esc(x.nombre)}: RD$ ${this.num(x.valor)}</title></rect>`}).join(''),arriba=y(p.valor),titulo=orden.map(x=>`${x.nombre}: RD$ ${this.num(x.valor)}`).join(' · ');return`<g class="gal-chart-item${activo?' activo':''}" data-dec-periodo="${this.esc(p.periodo)}" tabindex="0" role="button" aria-pressed="${activo}"><title>${this.esc(this.periodoDecomisoDO(p.periodo))}. ${this.esc(titulo||'Sin valor')}. Pulse para filtrar.</title>${detalle}<circle class="gal-chart-punto" cx="${centro}" cy="${arriba}" r="3.5"></circle><text class="gal-chart-mes" x="${centro}" y="${base+20}" text-anchor="middle">${this.esc(this.periodoCortoDecomiso(p.periodo))}</text><text class="gal-chart-valor" x="${centro}" y="${Math.max(margen.arr+9,arriba-7)}" text-anchor="middle">${this.esc(this.formatoEjeDecomiso(p.valor))}</text></g>`}).join(''),direccion=serie.length<2?'Sin comparación':pendiente>promedio*.015?'Ascendente':pendiente<-promedio*.015?'Descendente':'Estable',leyenda=nombres.map(nombre=>`<span><i class="gal-leyenda-departamento" style="--gal-serie-color:${this.colorDepartamentoDecomiso(nombre)}"></i>${this.esc(nombre)}</span>`).join('');
